#!/usr/bin/env python3
"""
Round 201o (culprits), 14 October 2026. Needs round 200o.

Box roll arrow; Streets box out; Official buildings and Land use in View; faster land use.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 201o (14 October)\n\nNeeds round 200o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Top right box: an arrow at the end of the Stuck? line pulls the whole\n  basemap and view box up and down (settingsRoll).\n- The Streets box is gone (on the picture basemaps the streets the owner saw\n  were in the place-name picture, so they went with Place names);\n  OpenStreetMap\'s details stay on (DETAILS_ON fixed true).\n- Under Place names: Official buildings (the Buildings row, now named\n  Government and official buildings) and Land use, ticking their rows in the\n  layers box, whose Buildings heading is hidden (settingsMirrors).\n- Land use was slow: it fetched and read a second copy of the same\n  OpenStreetMap tiles; it now draws from the map\'s own "osm" source, from\n  zoom 5 (edges from zoom 8).\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round201o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 200o" not in h.read_text(encoding="utf-8"):
        sys.exit("round201o: round 200o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round201o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/test.mjs", check=False)
            sys.exit("round201o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round201o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
